"""
Тест двусторонней связи через HC-05 (ZS-040):
    COM9  — FT232H (USB-UART), физически подключён к HC-05 по UART
    COM10 — виртуальный COM-порт Bluetooth (outgoing), paired с тем же HC-05

Ожидаемое поведение:
    write COM9  → read COM10
    write COM10 → read COM9
"""

import time
import serial

import serial.tools.list_ports

# ---------- Настройки ----------
USB_PORT = "COM9"     # FT232H
BT_PORT  = "COM11"    # Bluetooth outgoing
# BT_PORT_Send = "COM10"    # Bluetooth sending
BAUD     = 115200   # рабочая скорость HC-05 (AT+UART) команда настройки HC-05 AT+UART=115200,0,0

TIMEOUT  = 1.0        # сек, на чтение

import serial.tools.list_ports

def find_bluetooth_ports():
    """
    Сканирует COM-порты и определяет, какой из них исходящий (Outgoing),
    а какой входящий (Incoming) для Bluetooth SPP.

    Возвращает:
        (outgoing_port, incoming_port) или (None, None), если не найдены.
    """
    outgoing = None
    incoming = None

    for p in serial.tools.list_ports.comports():
        # Нас интересуют только порты Bluetooth (BTHENUM)
        if "BTHENUM" not in p.hwid:
            continue

        # Извлекаем адрес из строки hwid.
        # Пример hwid: ...\7&CC47540&0&209BA5420081_C00000000
        # Адрес находится между последним '&' и последним '_'.
        try:
            start = p.hwid.rfind("&")
            end = p.hwid.rfind("_")
            address_str = p.hwid[start + 1 : end]
            address = int(address_str, 16)
        except (ValueError, IndexError):
            # Если не удалось распарсить — пропускаем порт
            continue

        if address == 0:
            incoming = p.device
        else:
            outgoing = p.device

    print("incoming:", incoming)
    print("outgoing:", outgoing)
    return outgoing, incoming


    # Дальше можно сразу открывать исходящий порт:
    # import serial
    # bt = serial.Serial(out_port, 115200, timeout=1)


def open_port(name: str) -> serial.Serial:
    ser = serial.Serial(name, BAUD, timeout=TIMEOUT)
    time.sleep(0.2)                 # дать порту открыться
    ser.reset_input_buffer()
    ser.reset_output_buffer()
    return ser


def send_and_receive(tx_port, rx_port, payload: bytes, wait=0.5) -> bytes:
    """Отправляет payload в tx_port и читает ответ из rx_port."""
    tx_port.write(payload)
    tx_port.flush()
    time.sleep(wait)                # время на проход через UART + BT
    n = rx_port.in_waiting
    if n == 0:
        return b""
    return rx_port.read(n)

def warmup(bt: serial.Serial, ftdi: serial.Serial,
           attempts: int = 30, interval: float = 0.1) -> bool:
    """
    Прогрев BT-канала: шлём пробный байт через BT, ждём его на FT232H.
    Нужно, потому что Windows поднимает BT-соединение с задержкой
    ~0.5–2 с после открытия порта.
    """
    print("Прогрев BT-канала…")
    for n in range(1, attempts + 1):
        probe = b"\xAA\x55"
        bt.write(probe); bt.flush()
        time.sleep(interval)
        if ftdi.in_waiting >= len(probe):
            ftdi.read(ftdi.in_waiting)     # очистить
            bt.reset_input_buffer()
            print(f"  канал готов после {n} попыток")
            return True
    print(f"  канал НЕ готов за {attempts * interval:.1f} с")
    return False

def main():
    find_bluetooth_ports()

    print(f"Открываю {USB_PORT} (FT232H)  @ {BAUD} 8N1 …")
    usb = open_port(USB_PORT)
    print(f"Открываю {BT_PORT}  (Bluetooth outgoing) @ {BAUD} 8N1 …")
    bt = open_port(BT_PORT)
    # print(f"Открываю {BT_PORT_Send}  (Bluetooth sending) @ {BAUD} 8N1 …")
    # bt_send = open_port(BT_PORT_Send)
    # print("три порта открыты.\n")

    try:
        if not warmup(bt, usb):
            print("Канал не прогрелся. Проверьте:")
            print(f"  — HC-05 настроен на скорость {BAUD} (AT+UART={BAUD},0,0)")
            print("  — HC-05 перезагружен по питанию после AT-команды")
            print(f"  — {bt} действительно outgoing")
            return

        time.sleep(0.5)
        bt.reset_input_buffer()
        usb.reset_input_buffer()
        print()

        # ---------- Тест 1: USB → BT ----------
        print("=" * 60)
        print("[Тест 1] write USB → read COM11")
        msg = b"hello_from_ft232h"
        got = send_and_receive( usb, bt, msg)
        print(f"  Отправлено: {msg!r}")
        print(f"  Получено:   {got!r}")
        print(f"  Результат:  {'OK' if got == msg else 'FAIL'}")
        print()

        # ---------- Тест 2: BT → USB ----------
        print("[Тест 2] write COM11 → read COM9")
        msg = b"hello_from_bluetooth"
        got = send_and_receive(bt, usb, msg)
        print(f"  Отправлено: {msg!r}")
        print(f"  Получено:   {got!r}")
        print(f"  Результат:  {'OK' if got == msg else 'FAIL'}")
        print()

        # ---------- Тест 3: серия USB → BT ----------
        print("[Тест 3] Серия пакетов COM9 → COM10 (10 шт.)")
        ok = 0
        for i in range(10):
            m = f"pkt_{i:02d}".encode()
            got = send_and_receive(usb, bt, m, wait=0.2)
            status = "OK" if got == m else f"FAIL (got={got!r})"
            print(f"  {i:02d}: {status}")
            if got == m:
                ok += 1
        print(f"  Итого: {ok}/10")
        print()

        # ---------- Тест 4: серия BT → USB ----------
        print("[Тест 4] Серия пакетов COM10 → COM9 (10 шт.)")
        ok = 0
        for i in range(10):
            m = f"bpkt_{i:02d}".encode()
            got = send_and_receive(bt, usb, m, wait=0.2)
            status = "OK" if got == m else f"FAIL (got={got!r})"
            print(f"  {i:02d}: {status}")
            if got == m:
                ok += 1
        print(f"  Итого: {ok}/10")
        print()

        # ---------- Тест 5: бинарные данные ----------
        print("[Тест 5] Бинарные данные (все байты 0x00..0xFF)")
        payload = bytes(range(256))
        got = send_and_receive(usb, bt, payload, wait=1.0)
        print(f"  Отправлено: {len(payload)} байт")
        print(f"  Получено:   {len(got)} байт")
        print(f"  Совпадает:  {'OK' if got == payload else 'FAIL'}")
        if got != payload:
            # показать первое расхождение
            for i, (a, b) in enumerate(zip(payload, got)):
                if a != b:
                    print(f"  Первое расхождение в байте {i}: "
                          f"отправлено 0x{a:02X}, получено 0x{b:02X}")
                    break
        print()

        print("=" * 60)
        print("Тест завершён.")

    finally:
        usb.close()
        bt.close()
        print("Порты закрыты.")


if __name__ == "__main__":
    main()